def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find background color (most frequent)
    colors = {}
    for r in range(rows):
        for c in range(cols):
            cell = grid[r][c]
            colors[cell] = colors.get(cell, 0) + 1

    bg_color = max(colors, key=colors.get)

    # Find all non-background pixels
    pixels = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_color:
                pixels.append((r, c, grid[r][c]))

    # Create output grid filled with background
    output_grid = [[bg_color for _ in range(cols)] for _ in range(rows)]

    # Shift each pixel down by 1 row
    for r, c, val in pixels:
        new_r = r + 1
        if new_r < rows:
            output_grid[new_r][c] = val

    return output_grid
